ruleSearch.bookList:
.hot_sale[0:4]
<js>
bookList = result;
h = java.getStringList("a@href", bookList);

ht = h[1].includes("http") ? Array.from(h) : Array.from(h, x => `${source.key}${x}`);

d = java.ajaxAll(ht).map(x => x.body());

$=(b,c)=>java.getString(b,c);

Array.from(bookList,(a,i)=>{
	list={
		name:$(".title@text",a),
		author:$(".author.0@text##作者：",a),
		kind:$(".author.1@text##|",a),
		words:$("",d[i]),
		lastc:$(".author.2@text##最新章节：",a),
		intro:$(".review@textNodes",d[i]),
		cover:$(".synopsisArea_detail > img@src",d[i]),
		link:$("a@href",a)
		};
		return list
	});
</js>
